    const text = chars(String(value ?? '').replace(/\r\n?/g, '\n'));
    const lines = [{ chars: [], styles: [] }];
    let style = plain();
    for (let i = 0; i < text.length; i++) {
      const ch = text[i], next = (text[i + 1] || '').toLowerCase();
