            const root = document.documentElement;
            if (!wizard) return root.classList.remove('smk-fit');
            const height = Math.floor(innerHeight - (wizard.getBoundingClientRect().top + scrollY) - (root.classList.contains('ps-frame') ? 0 : 16));
